"""Self-extracting build of the animated GitHub profile README.

    python profile_bundle.py --photo path/to/your/photo.jpg

Writes every script, the workflow and the support files into the current
directory, then (unless --no-build) fetches your data and renders all six
SVGs plus README.md.

    --user USER    GitHub username to read the public calendar for
    --photo PATH   portrait source; skipped if omitted
    --extract      write the files and stop
"""
import argparse
import base64
import os
import subprocess
import sys

USER = "saurav158204"

FILES = {
    "scripts/panel.py":
        "",
    "scripts/gen_portrait.py":
        "",
    "scripts/gen_info_card.py":
        "",
    "scripts/gen_stack.py":
        "",
    "scripts/gen_signals.py":
        "",
    "scripts/gen_heatmap.py":
        "",
    "scripts/gen_stats.py":
        "",
    "scripts/gen_readme.py":
        "",
    "scripts/fetch_contributions.py":
        "",
    "scripts/fetch_profile.py":
        "",
    "scripts/verify_svgs.py":
        "",
    "scripts/make_bundle.py":
        "",
    ".github/workflows/refresh-heatmap.yml":
        "",
    "requirements.txt":
        "IyBGdWxsIHNldCwgZm9yIHJlZ2VuZXJhdGluZyB0aGUgcG9ydHJhaXQgbG9jYWxseS4KIyBUaGUgZGFpbHkgd29ya2Zsb3cgaW5zdGFsbHMgb25seSByZXF1ZXN0cyArIGJlYXV0aWZ1bHNvdXA0LgpyZXF1ZXN0cwpiZWF1dGlmdWxzb3VwNApwaWxsb3cKbnVtcHkKb3BlbmN2LXB5dGhvbgpyZW1iZwpvbm54cnVudGltZQo=",
    ".gitignore":
        "X19weWNhY2hlX18vCioucHljCi52ZW52Lwp2ZW52LwpwcmV2aWV3Ki5zdmcKcHJldmlldy5odG1sCi5jbGF1ZGUvCg==",
}


def extract():
    for path, blob in FILES.items():
        folder = os.path.dirname(path)
        if folder:
            os.makedirs(folder, exist_ok=True)
        data = base64.b64decode(blob).decode("utf-8")
        with open(path, "w", encoding="utf-8", newline="\n") as fh:
            fh.write(data)
        print(f"  wrote {path}")
    os.makedirs("data", exist_ok=True)
    os.makedirs("assets", exist_ok=True)


def run(*args):
    print("$ " + " ".join(args))
    if subprocess.call([sys.executable, *args]) != 0:
        raise SystemExit(f"failed: {' '.join(args)}")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--user", default=USER)
    ap.add_argument("--photo")
    ap.add_argument("--extract", action="store_true")
    ap.add_argument("--no-build", action="store_true")
    a = ap.parse_args()

    print("Extracting project files...")
    extract()
    if a.extract or a.no_build:
        print("\nDone. Install deps with:  pip install -r requirements.txt")
        return

    print("\nFetching public profile data...")
    run("scripts/fetch_contributions.py", "--user", a.user)
    run("scripts/fetch_profile.py", "--user", a.user)

    print("\nRendering panels...")
    if a.photo:
        run("scripts/gen_portrait.py", "--photo", a.photo)
    else:
        print("  (no --photo given, skipping the ASCII portrait)")
    run("scripts/gen_info_card.py")
    run("scripts/gen_stack.py")
    run("scripts/gen_signals.py")
    run("scripts/gen_heatmap.py")
    run("scripts/gen_stats.py")

    print("\nVerifying and writing README...")
    panels = [f for f in ("ascii-portrait.svg", "info-card.svg",
                          "contrib-heatmap.svg", "stack.svg",
                          "signals.svg", "stats.svg") if os.path.exists(f)]
    run("scripts/verify_svgs.py", *panels)

    # gen_readme solves the two panel widths from the portrait and the card,
    # so it needs the portrait to exist.
    if os.path.exists("ascii-portrait.svg"):
        run("scripts/gen_readme.py")
    else:
        print("  (README skipped - re-run with --photo to build the portrait)")

    print("\nAll done. Commit everything and push to saurav158204/saurav158204.")


if __name__ == "__main__":
    main()
